import pytest
from solution import parse_duration


def test_single_unit_seconds():
    assert parse_duration('45s') == 45


def test_single_unit_minutes():
    assert parse_duration('5m') == 300


def test_single_unit_hours():
    assert parse_duration('2h') == 7200


def test_combined_hours_and_minutes():
    assert parse_duration('1h30m') == 5400


def test_combined_all_units():
    assert parse_duration('1h2m3s') == 3723


def test_combined_minutes_and_seconds():
    assert parse_duration('10m15s') == 615


def test_combined_hours_and_seconds():
    assert parse_duration('2h45s') == 7245


def test_zero_value():
    assert parse_duration('0s') == 0


def test_zero_with_other_units():
    assert parse_duration('0h5m0s') == 300


def test_components_in_reverse_order():
    assert parse_duration('30s2m') == 150


def test_large_values():
    assert parse_duration('100h') == 360000


def test_empty_string_raises():
    with pytest.raises(ValueError):
        parse_duration('')


def test_missing_unit_raises():
    with pytest.raises(ValueError):
        parse_duration('10')


def test_unknown_unit_raises():
    with pytest.raises(ValueError):
        parse_duration('10x')


def test_non_integer_number_raises():
    with pytest.raises(ValueError):
        parse_duration('1.5h')


def test_duplicate_unit_raises():
    with pytest.raises(ValueError):
        parse_duration('1h2h')


def test_uppercase_unit_raises():
    with pytest.raises(ValueError):
        parse_duration('1H')


def test_space_in_input_raises():
    with pytest.raises(ValueError):
        parse_duration('1h 30m')
